extern int ksGlobalTextLanguage;
enum { LANGUAGE_FRENCH = 2, LANGUAGE_GERMAN = 3 };
extern bool file_finder_exists(const stringx& filename, const stringx& extension, stringx *stashname = 0);

class BeachFrontEnd {
public:
    char pad0[76];
    FEMenuEntry *highlighted;
    char pad1[2116];
    FEMenuEntry *fe_return;

    bool BeachBioExists(stringx& tmp);
};

bool BeachFrontEnd::BeachBioExists(stringx& tmp)
{
    if(highlighted == fe_return) return false;
    tmp = stringx("interface\\map\\beaches\\") + BeachDataArray[highlighted->entry_num].stashfile;
    if(ksGlobalTextLanguage == LANGUAGE_FRENCH)
        tmp += "_fr";
    else if(ksGlobalTextLanguage == LANGUAGE_GERMAN)
        tmp += "_ge";
    tmp += ".txt";
    return file_finder_exists(tmp, "");
}
